package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;

class MemoryBlankNodeReferenceScalarCompositionTest {
	@Test
	void nestedTripleExpressionsRemainScalarInsideExpressionCombinators() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = evaluate(connection);
			assertEquals(2, rows.size(), "scalar triple expressions over VALUES must not become graph lookups");

			var vf = connection.getValueFactory();
			var predicate = vf.createIRI("urn:p");
			var outer = vf.createIRI("urn:outer");
			var contains = vf.createIRI("urn:contains");
			Value fixedInner = vf.createTripleTerm(vf.createBNode("fixedSubject"), predicate,
					vf.createBNode("fixedObject"));
			TripleTerm constantNested = vf.createTripleTerm(outer, contains, fixedInner);
			Set<BNode> freshNodes = new HashSet<>();

			for (BindingSet row : rows) {
				String inputId = row.getValue("subjectInput").stringValue();
				Resource subject = vf.createBNode(inputId);
				String nestedSubjectId = inputId.equals("s1") ? "innerS1" : "innerS2";
				String nestedObjectId = inputId.equals("s1") ? "innerO1" : "innerO2";
				Value nestedObject = vf.createTripleTerm(vf.createBNode(nestedSubjectId), vf.createIRI("urn:nested"),
						vf.createBNode(nestedObjectId));
				Value dynamicInner = vf.createTripleTerm(subject, predicate, nestedObject);
				TripleTerm dynamicNested = vf.createTripleTerm(outer, contains, dynamicInner);

				assertEquals(subject, row.getValue("subject"));
				assertEquals(constantNested, row.getValue("constant"));
				assertEquals(dynamicNested, row.getValue("dynamic"));
				assertEquals(constantNested, row.getValue("coalesced"),
						"COALESCE must catch the invalid dynamic predicate and keep the scalar fallback");
				assertEquals(dynamicNested, row.getValue("conditional"),
						"IF must evaluate its selected scalar branch without evaluating the invalid branch");
				assertNull(row.getValue("error"),
						"a failing TRIPLE expression must leave only its BIND target unbound");
				assertTrue(row.getValue("fresh") instanceof BNode);
				BNode fresh = (BNode) row.getValue("fresh");
				assertNotEquals(vf.createBNode("fresh"), fresh,
						"BNODE(label) allocates a fresh identity instead of using the reference with the same label");
				assertEquals(vf.createLiteral(false), row.getValue("same"));
				assertTrue(freshNodes.add(fresh), "separate VALUES solution occurrences receive separate BNODE values");
			}
			assertEquals(2, freshNodes.size());
		} finally {
			repository.shutDown();
		}
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection) {
		String query = "SELECT ?subjectInput ?subject ?constant ?dynamic ?coalesced ?conditional ?error ?fresh ?same WHERE { "
				+ "VALUES (?subjectInput ?objectInput ?invalidPredicate) { "
				+ "(<_:s1> <<( <_:innerS1> <urn:nested> <_:innerO1> )>> <_:badPredicate1>) "
				+ "(<_:s2> <<( <_:innerS2> <urn:nested> <_:innerO2> )>> <_:badPredicate2>) } "
				+ "BIND(SUBJECT(TRIPLE(?subjectInput, <urn:p>, ?objectInput)) AS ?subject) "
				+ "BIND(TRIPLE(<urn:outer>, <urn:contains>, TRIPLE(<_:fixedSubject>, <urn:p>, <_:fixedObject>)) AS ?constant) "
				+ "BIND(TRIPLE(<urn:outer>, <urn:contains>, TRIPLE(?subjectInput, <urn:p>, ?objectInput)) AS ?dynamic) "
				+ "BIND(COALESCE(TRIPLE(?subjectInput, ?invalidPredicate, ?objectInput), "
				+ "TRIPLE(<urn:outer>, <urn:contains>, TRIPLE(<_:fixedSubject>, <urn:p>, <_:fixedObject>))) AS ?coalesced) "
				+ "BIND(IF(BOUND(?subjectInput), "
				+ "TRIPLE(<urn:outer>, <urn:contains>, TRIPLE(?subjectInput, <urn:p>, ?objectInput)), "
				+ "TRIPLE(?subjectInput, ?invalidPredicate, ?objectInput)) AS ?conditional) "
				+ "BIND(TRIPLE(?subjectInput, ?invalidPredicate, ?objectInput) AS ?error) "
				+ "BIND(BNODE(\"fresh\") AS ?fresh) "
				+ "BIND(sameTerm(?fresh, <_:fresh>) AS ?same) }";

		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				assertNotNull(row.getValue("subjectInput"));
				rows.add(row);
			}
		}
		return rows;
	}
}
